function smallestAround(ranges: number[][], points: number[]): number[] {
  return points.map(p => {
    let best = Infinity;
    for (const [l, r] of ranges) if (l <= p && p <= r) best = Math.min(best, r - l + 1);
    return best === Infinity ? -1 : best;
  });
}

