    def smallestAround(self, ranges: List[List[int]], points: List[int]) -> List[int]:
        out = []
        for p in points:
            sizes = [r - l + 1 for l, r in ranges if l <= p <= r]
            out.append(min(sizes) if sizes else -1)
        return out

