class Heap<T> {
  private a: T[] = [];
  constructor(private before: (x: T, y: T) => boolean) {}
  get size(): number { return this.a.length; }
  peek(): T { return this.a[0]; }
  push(x: T): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.before(a[i], a[p])) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): T {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.before(a[l], a[m])) m = l;
        if (r < a.length && this.before(a[r], a[m])) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function smallestAround(ranges: number[][], points: number[]): number[] {
  const rs = ranges.map(x => [x[0], x[1]]).sort((a, b) => a[0] - b[0]);
  const order = points.map((_, i) => i).sort((a, b) => points[a] - points[b]);
  const open = new Heap<number[]>((x, y) => x[0] < y[0]); // [size, right]
  const answer = new Array(points.length).fill(-1);
  let i = 0;
  for (const j of order) {
    const p = points[j];
    while (i < rs.length && rs[i][0] <= p) { open.push([rs[i][1] - rs[i][0] + 1, rs[i][1]]); i++; }
    while (open.size && open.peek()[1] < p) open.pop(); // ended: useless for this and every later point
    if (open.size) answer[j] = open.peek()[0];
  }
  return answer;
}

