            p = points[j]
            while i < len(rs) and rs[i][0] <= p:
                l, r = rs[i]
                heapq.heappush(heap, (r - l + 1, r))
                i += 1
            while heap and heap[0][1] < p:
                heapq.heappop(heap)  # ended before p, so also before every later point
            if heap:
                answer[j] = heap[0][0]
